function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Cue
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Cue', W/4, H/2);

  // Routine
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillText('Routine', W/2, H/2);

  // Reward
  ctx.beginPath();
  ctx.arc(3*W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillText('Reward', 3*W/4, H/2);

  // Loop
  ctx.beginPath();
  ctx.lineWidth = 5;
  ctx.moveTo(W/4, H/2);
  ctx.lineTo(W/2, H/2);
  ctx.lineTo(3*W/4, H/2);
  ctx.lineTo(W/4, H/2);
  ctx.stroke();

  // Habit loop animation
  ctx.beginPath();
  ctx.lineWidth = 3;
  ctx.moveTo(W/4 + 20 * Math.cos(t), H/2 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 20 * Math.cos(t + Math.PI/2), H/2 + 20 * Math.sin(t + Math.PI/2));
  ctx.lineTo(3*W/4 + 20 * Math.cos(t + Math.PI), H/2 + 20 * Math.sin(t + Math.PI));
  ctx.lineTo(W/4 + 20 * Math.cos(t + 3*Math.PI/2), H/2 + 20 * Math.sin(t + 3*Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
